def load_merkle_data():
    """Load merkle_data.json and validate hashes."""
    data_path = Path('/app/merkle_data.json')
    if not data_path.exists():
        return None

    with open(data_path, 'r') as f:
        data = json.load(f)

    # Validate hashes are 128-char hex strings
    def validate_hash(h):
        return isinstance(h, str) and len(h) == 128 and all(c in '0123456789abcdef' for c in h)

    if not validate_hash(data.get('root_hash', '')):
        return None

    for fp, h in data.get('file_hashes', {}).items():
        if not validate_hash(h):
            return None

    for fp, proof in data.get('proofs', {}).items():
        for entry in proof:
            if len(entry) != 2 or not validate_hash(entry[1]):
                return None

    return data


def cmd_scan(args):
    """Scan directory and build Merkle tree."""
    directory = Path(args.directory)
    if not directory.exists():
        print(f"Error: Directory '{directory}' does not exist", file=sys.stderr)
        return 1

    if not directory.is_dir():
        print(f"Error: '{directory}' is not a directory", file=sys.stderr)
        return 1

    tree = MerkleTree()
    tree.build_from_directory(directory)

    data = tree.to_dict(directory.resolve())

    with open('/app/merkle_data.json', 'w') as f:
        json.dump(data, f, indent=2)

    print(f"Scanned {len(tree.leaves)} files")
    print(f"Root hash: {tree.root_hash}")
    return 0


def cmd_proof(args):
    """Generate Merkle proof for a file."""
    data = load_merkle_data()
    if data is None:
        print("Error: No merkle_data.json found. Run scan first.", file=sys.stderr)
        return 1

    file_path = args.file_path

    if file_path not in data['file_hashes']:
