        return 1

    proof = data['proofs'].get(file_path, [])

    output = {
        "file_path": file_path,
        "proof": proof
    }

    print(json.dumps(output, indent=2))
    return 0


def cmd_verify(args):
    """Verify a file's integrity against stored proof."""
    data = load_merkle_data()
    if data is None:
        print("Error: No merkle_data.json found. Run scan first.", file=sys.stderr)
        return 1

    file_path = args.file_path
    proof_file = Path(args.proof_file)

    # Load proof from file
    if not proof_file.exists():
        print(f"Error: Proof file '{proof_file}' does not exist", file=sys.stderr)
        return 1

    with open(proof_file, 'r') as f:
        proof_data = json.load(f)

    # Get current hash of the file
    try:
        # Try relative path first (from scanned directory)
        scanned_dir = Path(data['scanned_directory'])
        abs_path = scanned_dir / file_path

        if not abs_path.exists():
            # Try as absolute path
            abs_path = Path(file_path)
            if not abs_path.exists():
                print(f"Error: File not found: {file_path}", file=sys.stderr)
                return 1

        with open(abs_path, 'rb') as f:
            current_hash = sha512_hash(f.read())
    except Exception as e:
        print(f"Error reading file: {e}", file=sys.stderr)
        return 1

    # Reconstruct root from proof
    current = current_hash
    for side, sibling in proof_data['proof']:
        if side == "left":
            current = sha512_concatenate(sibling, current)
        else:
            current = sha512_concatenate(current, sibling)

    # Check results
    root_matches = (current == data['root_hash'])
    file_hash_matches_storage = (current_hash == data['file_hashes'].get(file_path))

    # Check for added/deleted files
    stored_files = set(data['file_hashes'].keys())

    # Get current files in scanned directory
    scanned_dir = Path(data['scanned_directory'])
    current_files = set()
    if scanned_dir.exists():
        for item in scanned_dir.rglob('*'):
            if item.is_file() and not item.is_symlink():
                rel_path = str(item.relative_to(scanned_dir))
                current_files.add(rel_path)

    added_files = current_files - stored_files
    deleted_files = stored_files - current_files

    # Check for modified files
    modified_files = set()
    for fp in stored_files & current_files:
        if fp != file_path:  # Don't check the file we're verifying
            abs_fp = scanned_dir / fp
            if abs_fp.exists():
                with open(abs_fp, 'rb') as f:
                    stored_hash = data['file_hashes'][fp]
                    current_h = sha512_hash(f.read())
                    if stored_hash != current_h:
                        modified_files.add(fp)

    success = root_matches and file_hash_matches_storage and not added_files and not deleted_files and not modified_files

    output = {
        "file_path": file_path,
        "root_matches": root_matches,
        "file_hash_matches_storage": file_hash_matches_storage,
        "added_files": list(added_files),
        "deleted_files": list(deleted_files),
        "modified_files": list(modified_files)
    }

    if success:
        print("Verification successful!")
        print(f"File hash: {current_hash}")
        print(f"Root hash matches: {root_matches}")
        return 0
    else:
        print("Verification failed!")
        print(json.dumps(output, indent=2))
        return 1


def main():
    parser = argparse.ArgumentParser(description='Merkle Tree CLI Tool')
    subparsers = parser.add_subparsers(dest='command', required=True)

    # Scan command
    scan_parser = subparsers.add_parser('scan', help='Scan directory and build Merkle tree')
    scan_parser.add_argument('directory', help='Directory to scan')

    # Proof command
    proof_parser = subparsers.add_parser('proof', help='Generate Merkle proof for a file')
    proof_parser.add_argument('file_path', help='File path (relative to scanned directory)')

    # Verify command
    verify_parser = subparsers.add_parser('verify', help='Verify file integrity')
    verify_parser.add_argument('file_path', help='File path to verify')
    verify_parser.add_argument('proof_file', help='Path to proof JSON file')

    args = parser.parse_args()

    if args.command == 'scan':
        return cmd_scan(args)
    elif args.command == 'proof':
        return cmd_proof(args)
    elif args.command == 'verify':
        return cmd_verify(args)

    return 1


if __name__ == '__main__':
    sys.exit(main())
